const drawer=document.getElementById('evidence-drawer');function closeDrawer(){drawer.classList.add('hidden')}
function showEvidence(id){const item=evidence[id];if(!item)return;document.getElementById('evidence-title').textContent=id;const content=document.getElementById('evidence-content');content.innerHTML='';const intro=document.createElement('p');intro.textContent='报告引用的来源对象与版本。以下内容为模拟证据示例。';const dl=document.createElement('dl');for(const [name,value] of [['类型',item.type],['来源对象',item.source],['来源版本',item.version],['检索时间',item.time]]){const row=document.createElement('div'),dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=name;dd.textContent=value;row.append(dt,dd);dl.append(row)}const quote=document.createElement('div');quote.className='excerpt';quote.textContent=item.excerpt;content.append(intro,dl,quote);drawer.classList.remove('hidden')}
document.querySelectorAll('[data-evidence]').forEach(el=>el.addEventListener('click',()=>showEvidence(el.dataset.evidence)));document.getElementById('drawer-close').addEventListener('click',closeDrawer);drawer.addEventListener('click',e=>{if(e.target===drawer)closeDrawer()});

const approvalCases=[{task:'QI-240817',approval:'APR-240817',title:'金属阀体外缘异常',batch:'BA-2026-1042',version:'v1',risk:'高风险',stage:'ENGINEER',detection:'发现异常 · 分数 0.87',evidence:'4 条有效引用',sufficiency:'不足以确认根因',warning:'缺少同批次复核图像及设备事件记录。建议先补拍与抽检。',history:'报告 v1 · 今天 10:41 生成；审批请求今天 10:42 创建。',status:'待审批',comment:''},{task:'QI-240813',approval:'APR-240813',title:'阀体表面纹理异常',batch:'BA-2026-1036',version:'v1',risk:'中风险',stage:'ENGINEER',detection:'发现异常 · 分数 0.79',evidence:'3 条有效引用',sufficiency:'仍需现场复核',warning:'历史案例相似，但尚无本批次的复拍图像。',history:'报告 v1 · 昨天 11:31 生成；审批请求昨天 11:32 创建。',status:'待审批',comment:''},{task:'QI-240811',approval:'APR-240811',title:'复检图像需二次确认',batch:'BA-2026-1034',version:'v2',risk:'低风险',stage:'ENGINEER',detection:'结果不确定 · 分数 0.71',evidence:'2 条有效引用',sufficiency:'需补充证据',warning:'报告 v1 曾退回补证；v2 增加了复拍图像，仍需核对现场记录。',history:'报告 v1 · 前天生成并退回补证；报告 v2 · 昨天 09:07 生成。',status:'待审批',comment:''}];
let activeApproval=0;
document.querySelector('.approval-detail').insertAdjacentHTML('beforeend','<div class="approval-history"><h3>报告与审批版本</h3><p id="approval-history-text"></p></div>');
document.querySelector('.approval-detail').insertAdjacentHTML('beforeend','<div class="version-compare hidden" id="version-compare"><div class="compare-title"><h3>报告版本对比 · QI-240811</h3><span>历史不可覆盖</span></div><div class="compare-grid"><div><b>报告 v1 · 已退回补证</b><p>仅 1 条有效引用，缺少复拍图像；未形成正式工单。</p><small>审批意见：请补拍并核对现场记录。</small></div><div><b>报告 v2 · 当前待审</b><p>新增复拍图像证据 <button data-evidence="EV-R-811">EV-R-811 ↗</button>；仍缺少现场记录。</p><small>证据充分性：需补充证据。</small></div></div><div class="compare-note">版本差异只描述新增材料与判断变化。v1 报告、证据及退回意见继续可查。</div></div>');
document.querySelector('#version-compare [data-evidence]').addEventListener('click',()=>showEvidence('EV-R-811'));
function renderApproval(){const item=approvalCases[activeApproval],panel=document.querySelector('.approval-detail'),facts=panel.querySelectorAll('.review-facts strong'),status=document.getElementById('approval-status');panel.querySelector('.approval-detail-top .eyebrow').textContent='当前审批 · '+item.approval+' · '+(item.stage==='MANAGER'?'主管共同确认':'工程师审核');panel.querySelector('h2').textContent=item.task+' · '+item.title;panel.querySelector(':scope > p').textContent='批次 '+item.batch+' · 报告版本 '+item.version;facts[0].textContent=item.detection;facts[1].textContent=item.evidence;facts[2].textContent=item.sufficiency;panel.querySelector('.review-warning span').textContent=item.warning;panel.querySelector('.inline-link').classList.toggle('hidden',activeApproval!==0);panel.querySelector('.approval-note em').textContent=item.risk==='高风险'?'工程师与主管各阶段必填':'驳回与退回补证必填';document.getElementById('approval-comment').value=item.comment;document.getElementById('approval-error').textContent='';document.getElementById('approval-history-text').textContent=item.history;document.getElementById('version-compare').classList.toggle('hidden',activeApproval!==2);status.textContent=item.status;status.className='tag '+(item.status.startsWith('待')?'amber':item.status.startsWith('已批准')?'green':'gray');const primary=panel.querySelector('[data-decision="approve"]');primary.textContent=item.risk==='高风险'?(item.stage==='ENGINEER'?'工程师批准，送主管复核':'主管共同批准并创建工单'):'批准并创建工单';const allowed=(currentRole==='review'&&item.stage==='ENGINEER')||(item.stage==='ENGINEER'&&currentRole==='engineer')||(item.stage==='MANAGER'&&currentRole==='manager');panel.querySelectorAll('[data-decision]').forEach(button=>button.disabled=!allowed||!item.status.startsWith('待'));document.querySelectorAll('.queue-item').forEach((button,index)=>button.classList.toggle('selected',index===activeApproval))}
document.querySelectorAll('.queue-item').forEach((button,index)=>button.addEventListener('click',()=>{activeApproval=index;renderApproval()}));
renderApproval();
document.getElementById('approval-comment').addEventListener('input',event=>{approvalCases[activeApproval].comment=event.target.value});
document.querySelectorAll('[data-decision]').forEach(el=>el.addEventListener('click',()=>{const item=approvalCases[activeApproval],decision=el.dataset.decision,comment=document.getElementById('approval-comment').value.trim(),error=document.getElementById('approval-error');const allowed=(currentRole==='review'&&item.stage==='ENGINEER')||(item.stage==='ENGINEER'&&currentRole==='engineer')||(item.stage==='MANAGER'&&currentRole==='manager');if(!allowed){toast('当前阶段需由对应角色审批。');return}if((decision!=='approve'||item.risk==='高风险')&&!comment){error.textContent=item.risk==='高风险'?'高风险工程师与主管审批均需填写判断依据。':'驳回或退回补证时，请填写审批意见。';return}error.textContent='';if(!item.status.startsWith('待')){toast('此报告版本已有最终决定。');return}const labels={approve:'批准',reject:'驳回',return:'退回补证'},isHigh=item.risk==='高风险',engineerStage=item.stage==='ENGINEER';const body=decision==='approve'&&isHigh&&engineerStage?`工程师批准 ${item.task} 报告 ${item.version} 后，仅转入主管共同审批；此时不会创建工单。`:decision==='approve'?`主管或工程师最终批准 ${item.task} 报告 ${item.version} 后，业务服务才会创建正式工单。`:`决定将记录在 ${item.task} 报告 ${item.version} 的审批历史中，不创建工单。`;openModal({title:decision==='approve'&&isHigh?'确认高风险审批决定？':'确认'+labels[decision]+'报告？',body,extra:`审批对象：${item.approval} · 报告版本 ${item.version} · 本地设计演示。`,confirm:'确认'+labels[decision],action:()=>{if(decision==='approve'&&isHigh&&engineerStage){item.stage='MANAGER';item.status='待主管共同审批';item.history+=' 工程师批准并记录依据：'+comment+'；等待不同账户主管确认。';item.comment=''}else{item.status={approve:'已批准（演示）',reject:'已驳回（演示）',return:'已退回（演示）'}[decision];item.history+=' 最终决定：'+labels[decision]+'；依据：'+comment+'。'}renderApproval();toast('已更新本地审批阶段；未调用真实接口。')}})}));

document.querySelectorAll('[data-order]').forEach(el=>el.addEventListener('click',()=>{const pass=el.dataset.order==='pass',status=document.getElementById('order-status');if(status.textContent!=='待复检'){toast('当前演示工单已更新；请刷新页面恢复初始状态。');return}openModal({title:pass?'确认复检通过并关闭？':'确认复检不通过并返工？',body:pass?'工程师确认复检合格后，工单将进入已关闭状态。':'工单将返回处理中，原处置记录继续保留。',extra:'工单 WO-240809 · 此操作仅用于设计演示。',confirm:pass?'确认关闭':'确认返工',action:()=>{status.textContent=pass?'已关闭（演示）':'处理中（演示）';status.className='tag '+(pass?'green':'amber');toast('已更新本地演示工单状态；未写入真实系统。')}})}));

const roleOverlay=document.getElementById('role-overlay');let selectedRole='review';
function openRolePreview(){selectedRole=currentRole;document.querySelectorAll('[data-role]').forEach(button=>button.classList.toggle('selected',button.dataset.role===selectedRole));roleOverlay.classList.remove('hidden')}
function closeRolePreview(){roleOverlay.classList.add('hidden')}
document.getElementById('role-trigger').addEventListener('click',openRolePreview);document.getElementById('role-top').addEventListener('click',openRolePreview);document.getElementById('role-close').addEventListener('click',closeRolePreview);document.getElementById('role-cancel').addEventListener('click',closeRolePreview);roleOverlay.addEventListener('click',e=>{if(e.target===roleOverlay)closeRolePreview()});
document.querySelectorAll('[data-role]').forEach(button=>button.addEventListener('click',()=>{selectedRole=button.dataset.role;document.querySelectorAll('[data-role]').forEach(item=>item.classList.toggle('selected',item===button))}));
function applyRole(role){currentRole=role;const config=roles[role];document.getElementById('sidebar-user').textContent=config.label;document.getElementById('sidebar-role').textContent=config.desc;document.getElementById('sidebar-avatar').textContent=config.short;document.getElementById('top-avatar').textContent=config.short;document.querySelectorAll('.nav-item[data-view]').forEach(item=>item.classList.toggle('hidden',!config.views.includes(item.dataset.view)));document.querySelectorAll('[data-go]').forEach(item=>item.classList.toggle('hidden',!config.views.includes(item.dataset.go)));document.querySelectorAll('[data-decision],[data-order],#assignment-form button[type="submit"],#handling-form button[type="submit"]').forEach(item=>{item.disabled=!['review','engineer','manager'].includes(role)});document.querySelectorAll('#inspection-form button[type="submit"],#reinspection-form button[type="submit"]').forEach(item=>item.disabled=!['review','inspector'].includes(role));renderApproval();if(!config.views.includes(currentView))showView('overview');toast('已切换为'+config.label+'视图；权限只在界面原型中预览。')}
document.getElementById('role-confirm').addEventListener('click',()=>{closeRolePreview();applyRole(selectedRole)});

const statePreview={abnormal:{task:'待审批',taskClass:'amber',result:'发现异常',resultClass:'red',score:'0.87',meter:'87%',message:'视觉定位只指出疑似异常区域。实际原因需要结合批次、SOP 和历史案例调查。',report:true},normal:{task:'已完成',taskClass:'green',result:'正常检测',resultClass:'green',score:'0.18',meter:'18%',message:'当前演示结果满足正常质量门条件，任务完成且不创建异常工单。质检员仍可申请人工复核。',report:false},uncertain:{task:'待人工复核',taskClass:'amber',result:'结果不确定',resultClass:'amber',score:'0.74',meter:'74%',message:'检测结果接近阈值或可信度不足，必须进入调查与人工复核；不可自动放行。',report:true},error:{task:'需人工处理',taskClass:'gray',result:'检测失败',resultClass:'gray',score:null,meter:null,message:'检测服务超时。系统记录错误并转人工处理，不显示正常结论。可由授权人员发起受控重试。',report:false},evidence:{task:'需人工处理',taskClass:'gray',result:'发现异常',resultClass:'red',score:'0.87',meter:'87%',message:'报告引用的证据 ID 或版本未通过核验。系统保留失败记录并要求人工检查，不会把该报告送入正常审批。',report:false},budget:{task:'需人工处理',taskClass:'amber',result:'发现异常',resultClass:'red',score:'0.87',meter:'87%',message:'调查工具调用达到预算上限。分析已停止，报告需标明证据不足并转人工复核。',report:false}};
document.getElementById('detection-state').addEventListener('change',e=>{const state=statePreview[e.target.value],taskTag=document.getElementById('detail-task-status'),resultTag=document.querySelector('.result-panel .card-head .tag'),scoreBlock=document.querySelector('.score-block'),reportEntry=document.getElementById('report-entry'),heatButton=document.querySelector('[data-image-mode="heatmap"]');taskTag.textContent=state.task;taskTag.className='tag title-tag '+state.taskClass;resultTag.textContent=state.result;resultTag.className='tag '+state.resultClass;scoreBlock.classList.toggle('hidden',!state.score);if(state.score){scoreBlock.querySelector('strong').textContent=state.score;scoreBlock.querySelector('.score-meter span').style.width=state.meter}document.querySelector('.result-alert').textContent=state.message;reportEntry.disabled=!state.report;heatButton.disabled=!state.score;if(!state.score){document.querySelector('[data-image-mode="original"]').click()}});

document.getElementById('reinspection-form').addEventListener('submit',e=>{e.preventDefault();if(!['review','inspector'].includes(currentRole)){toast('只有质检员可以提交复检材料。');return}const file=document.getElementById('reinspection-image').files[0],result=document.querySelector('[name="reinspection-result"]:checked'),note=document.getElementById('reinspection-note').value.trim();let valid=true;if(!file||!['image/jpeg','image/png'].includes(file.type)||file.size>20*1024*1024){document.getElementById('reinspection-image-error').textContent='请选择不超过 20 MB 的 JPG 或 PNG 图像。';valid=false}else document.getElementById('reinspection-image-error').textContent='';if(!result){document.getElementById('reinspection-result-error').textContent='请选择观察结论。';valid=false}else document.getElementById('reinspection-result-error').textContent='';if(!note){document.getElementById('reinspection-note-error').textContent='请填写观察说明。';valid=false}else document.getElementById('reinspection-note-error').textContent='';if(!valid)return;const uncertain=result.value==='uncertain';openModal({title:'确认提交复检记录？',body:uncertain?'“无法判断”将保持工单待复检；工程师需要求重新取样或补拍，随后提交新一轮复检，不能据此关闭工单。':'提交后质检员的观察结论将进入待工程师确认状态，不会自动关闭工单。',extra:`工单 WO-240810 · 图像 ${file.name} · 结论 ${result.value}。当前仅为本地原型演示。`,confirm:'确认提交',action:()=>toast(uncertain?'无法判断：保持待复检，等待工程师要求补拍。':'复检提交交互已演示；未上传文件或写入系统。')})});

document.querySelectorAll('.order-item').forEach((item,index)=>item.addEventListener('click',()=>{document.querySelectorAll('.order-item').forEach(button=>button.classList.toggle('active',button===item));const grid=document.querySelector('.order-grid'),detail=document.querySelector('.order-detail'),actionPanel=document.getElementById('order-action-panel'),closedPanel=document.getElementById('closed-order-panel'),next=document.querySelector('.order-next');next.after(actionPanel,closedPanel);detail.classList.toggle('hidden',index!==0);actionPanel.classList.toggle('hidden',index!==1);closedPanel.classList.toggle('hidden',index!==2);const selected=[detail,actionPanel,closedPanel][index];if(index!==0)grid.appendChild(selected);selected.scrollIntoView({behavior:'smooth',block:'start'})}));

document.getElementById('list-state').addEventListener('change',event=>{const state=event.target.value,table=document.querySelector('#overview .table-wrap'),placeholder=document.getElementById('list-placeholder'),hint=document.querySelector('.scroll-hint');table.classList.toggle('hidden',state!=='ready');hint.classList.toggle('hidden',state!=='ready');placeholder.classList.toggle('hidden',state==='ready');const messages={loading:'正在加载任务… 请稍候。',empty:'当前范围内暂无检测任务。可新建检测开始记录。',error:'任务列表加载失败。请重试；若持续失败，使用追踪 ID 联系管理员。'};placeholder.textContent=messages[state]||'';placeholder.className='list-placeholder '+(state==='ready'?'hidden':state==='error'?'is-error':'');if(state==='error'){const retry=document.createElement('button');retry.className='btn secondary';retry.textContent='重试加载';retry.addEventListener('click',()=>{document.getElementById('list-state').value='ready';document.getElementById('list-state').dispatchEvent(new Event('change'));toast('已恢复演示列表；真实系统需重新请求任务 API。')});placeholder.appendChild(retry)}});

function addActionEvent(message){const row=document.createElement('div'),time=document.createElement('time'),span=document.createElement('span');time.textContent='刚刚';span.textContent=message+' · 本地演示';row.append(time,span);document.getElementById('action-events').prepend(row)}
document.getElementById('assignment-form').addEventListener('submit',event=>{event.preventDefault();const person=document.getElementById('assignee').value,reason=document.getElementById('assignment-reason').value.trim();document.getElementById('assignee-error').textContent=person?'':'请选择负责人。';document.getElementById('assignment-error').textContent=reason?'':'请填写分派原因。';if(!person||!reason)return;openModal({title:'确认重新分派工单？',body:`WO-240806 将分派给 ${person}，原负责人记录会保留。`,extra:'原因：'+reason+'。此操作仅为本地原型演示。',confirm:'确认分派',action:()=>{addActionEvent('重新分派给'+person+'；原因：'+reason);toast('分派事件已加入本地演示历史。')}})});
document.getElementById('handling-form').addEventListener('submit',event=>{event.preventDefault();const cause=document.getElementById('handling-cause').value.trim(),action=document.getElementById('handling-action').value.trim();document.getElementById('cause-error').textContent=cause?'':'请填写调查结论或待验证原因。';document.getElementById('action-error').textContent=action?'':'请写明具体处置措施。';if(!cause||!action)return;const status=document.getElementById('action-order-status');if(status.textContent!=='处理中'){toast('该演示工单已进入待复检。');return}openModal({title:'提交处置并进入待复检？',body:'处置版本会保留，质检员提交新图像后仍需工程师确认。',extra:'工单 WO-240806 · 此操作仅为本地演示。',confirm:'确认提交',action:()=>{status.textContent='待复检（演示）';status.className='tag blue';addActionEvent('提交处置记录并进入待复检');toast('已更新本地演示状态；未写入真实工单。')}})});

const adminPanel=document.querySelector('.admin-panel');
adminPanel.insertAdjacentHTML('beforeend','<div class="context-bar"><span class="context-icon">ⓘ</span> 账户仅由本租户管理员创建，不开放自助注册。真实系统生成随机临时密码，只在创建响应展示一次；首次登录必须修改。</div>');
adminPanel.insertAdjacentHTML('beforeend','<form class="admin-editor hidden" id="admin-editor" novalidate><div class="card-head"><div><h3 id="admin-editor-title">调整用户</h3><p>角色和账户状态的变化需说明原因</p></div><button type="button" class="editor-close" id="admin-editor-close" aria-label="关闭">×</button></div><div class="admin-editor-grid"><label class="field">账号 <span>*</span><input id="admin-account" type="text" placeholder="如 user.demo"></label><label class="field">姓名 <span>*</span><input id="admin-name" type="text" placeholder="用户姓名"></label><label class="field">角色 <span>*</span><select id="admin-role"><option value="质检员">质检员</option><option value="质量工程师">质量工程师</option><option value="质量主管">质量主管</option><option value="系统管理员">系统管理员</option><option value="审计员">审计员</option></select></label><label class="field">账户状态 <span>*</span><select id="admin-status"><option value="启用">启用</option><option value="停用">停用</option></select></label></div><label class="field">修改原因 <span>*</span><textarea id="admin-reason" rows="3" placeholder="说明添加账户或调整权限的原因"></textarea></label><small class="field-error" id="admin-form-error"></small><div class="editor-actions"><button type="button" class="btn ghost" id="admin-editor-cancel">取消</button><button type="submit" class="btn primary">保存演示变更</button></div></form>');
let editingUser=null;
function closeAdminEditor(){document.getElementById('admin-editor').classList.add('hidden');editingUser=null}
function openAdminEditor(row=null){editingUser=row;const editor=document.getElementById('admin-editor');editor.classList.remove('hidden');document.getElementById('admin-editor-title').textContent=row?'调整 '+row.dataset.user+' 的权限':'添加演示用户';document.getElementById('admin-account').value=row?row.querySelector('td small').textContent:'';document.getElementById('admin-account').disabled=!!row;document.getElementById('admin-name').value=row?row.dataset.user:'';document.getElementById('admin-role').value=row?row.querySelector('.user-role').textContent:'质检员';document.getElementById('admin-status').value=row?row.querySelector('.user-status').textContent:'启用';document.getElementById('admin-reason').value='';document.getElementById('admin-form-error').textContent='';editor.scrollIntoView({behavior:'smooth',block:'center'})}
document.getElementById('add-user').addEventListener('click',()=>openAdminEditor());
document.getElementById('admin-users').addEventListener('click',event=>{const button=event.target.closest('.edit-user');if(button)openAdminEditor(button.closest('tr'))});
document.getElementById('admin-editor-close').addEventListener('click',closeAdminEditor);document.getElementById('admin-editor-cancel').addEventListener('click',closeAdminEditor);
document.getElementById('admin-editor').addEventListener('submit',event=>{event.preventDefault();const account=document.getElementById('admin-account').value.trim(),name=document.getElementById('admin-name').value.trim(),role=document.getElementById('admin-role').value,status=document.getElementById('admin-status').value,reason=document.getElementById('admin-reason').value.trim(),error=document.getElementById('admin-form-error');if(!account||!name||!reason){error.textContent='请填写账号、姓名和修改原因。';return}if(!editingUser&&Array.from(document.querySelectorAll('#admin-users td small')).some(el=>el.textContent===account)){error.textContent='演示账号已存在。';return}error.textContent='';openModal({title:editingUser?'确认调整用户权限？':'确认添加演示用户？',body:`${name} · ${role} · ${status}。变更将在本地演示表格和事件历史中显示。`,extra:'原因：'+reason+'。真实系统还需权限校验与审计写入。',confirm:'确认保存',action:()=>{let row=editingUser;if(!row){row=document.createElement('tr');row.innerHTML='<td><strong></strong><small></small></td><td><span class="user-role"></span></td><td><span class="tag user-status"></span></td><td>刚刚</td><td><button class="link-btn edit-user">调整角色</button></td>';document.getElementById('admin-users').appendChild(row)}row.dataset.user=name;row.querySelector('td strong').textContent=name;row.querySelector('td small').textContent=account;row.querySelector('.user-role').textContent=role;row.querySelector('.user-status').textContent=status;row.querySelector('.user-status').className='tag user-status '+(status==='启用'?'green':'gray');const note=document.createElement('p'),stamp=document.createElement('b');stamp.textContent='刚刚 ';note.append(stamp,document.createTextNode((editingUser?'调整':'添加')+'用户 '+name+' · '+role+' · '+status+' · 原因：'+reason+' · 本地演示'));document.getElementById('admin-events').prepend(note);closeAdminEditor();toast('用户管理演示状态已更新；未写入真实账户系统。')}})});
